const TopBlatHelper = {
  getBySlug: function(slug) {
    return TOP_BLAT_CATALOG.find(p => p.slug === slug);
  },
  getByBrand: function(brand) {
    return TOP_BLAT_CATALOG.filter(p => p.brand.toLowerCase() === brand.toLowerCase());
  },
  getByColor: function(colorFamily) {
    return TOP_BLAT_CATALOG.filter(p => p.color_family.toLowerCase().includes(colorFamily.toLowerCase()));
  },
  search: function(query) {
    const q = query.toLowerCase();
    return TOP_BLAT_CATALOG.filter(p => 
      p.title.toLowerCase().includes(q) || 
      p.brand.toLowerCase().includes(q) || 
      p.slug.toLowerCase().includes(q)
    );
  }
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { TOP_BLAT_CATALOG, TOP_BLAT_PROJECTS, TopBlatHelper };
}
